import time
from collections import OrderedDict

class Cache:
    def __init__(self, capacity, clock=None):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self._clock = time.monotonic if clock is None else clock
        self._d = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _expired(self, key):
        _, exp = self._d[key]
        return exp is not None and self._clock() >= exp

    def get(self, key, default=None):
        if key not in self._d:
            self._misses += 1
            return default
        if self._expired(key):
            del self._d[key]
            self._misses += 1
            self._expirations += 1
            return default
        self._d.move_to_end(key)
        self._hits += 1
        return self._d[key][0]

    def put(self, key, value, ttl=None):
        exp = None if ttl is None else self._clock() + ttl
        if key in self._d:
            self._d.move_to_end(key)
        self._d[key] = (value, exp)
        while len(self._d) > self.capacity:
            self._evict()

    def _evict(self):
        self._d.popitem(last=False)
        self._evictions += 1

    def stats(self):
        looked = self._hits + self._misses
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
            "hit_rate": round(self._hits / looked, 4) if looked else 0.0,
        }

    def keys(self):
        return list(self._d)

    def __len__(self):
        return len(self._d)

