import time
from collections import OrderedDict

_MISSING = object()

class Cache:
    def __init__(self, capacity, clock=None, on_evict=None):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self._clock = time.monotonic if clock is None else clock
        self._on_evict = on_evict
        self._d = OrderedDict()
        self._hits = self._misses = self._evictions = self._expirations = 0

    def _expired(self, key):
        _, exp = self._d[key]
        return exp is not None and self._clock() >= exp

    def _remove(self, key, reason):
        value, _ = self._d.pop(key)
        if reason == "capacity":
            self._evictions += 1
        if self._on_evict is not None:
            try:
                self._on_evict(key, value, reason)
            except Exception:
                pass

    def get(self, key, default=None):
        if key not in self._d:
            self._misses += 1
            return default
        if self._expired(key):
            self._expirations += 1
            self._misses += 1
            self._remove(key, "expired")
            return default
        self._d.move_to_end(key)
        self._hits += 1
        return self._d[key][0]

    def put(self, key, value, ttl=None):
        exp = None if ttl is None else self._clock() + ttl
        if key in self._d:
            self._d.move_to_end(key)
        self._d[key] = (value, exp)
        while len(self._d) > self.capacity:
            self._remove(next(iter(self._d)), "capacity")

    def get_or_compute(self, key, fn, ttl=None):
        found = self.get(key, _MISSING)
        if found is not _MISSING:
            return found
        value = fn()
        self.put(key, value, ttl=ttl)
        return value

    def stats(self):
        looked = self._hits + self._misses
        return {
            "hits": self._hits, "misses": self._misses,
            "evictions": self._evictions, "expirations": self._expirations,
            "hit_rate": round(self._hits / looked, 4) if looked else 0.0,
        }

    def keys(self):
        return list(self._d)

    def __len__(self):
        return len(self._d)

def build_tree(samples):
    root = {}
    for stack in samples:
        level = root
        for frame in stack:
            node = level.setdefault(frame, {"count": 0, "children": {}})
            node["count"] += 1
            level = node["children"]
    return root

