def group_files(files, key=None):
    groups = {}
    for path, content in files.items():
        fp = content if key is None else key(content)
        groups.setdefault(fp, []).append(path)
    dupes = [sorted(paths) for paths in groups.values() if len(paths) > 1]
    dupes.sort(key=lambda g: g[0])
    return dupes

def normalize(content):
    lines = [ln.strip() for ln in content.lower().splitlines()]
    return "\n".join(ln for ln in lines if ln)

def exact_dupes(files):
    return group_files(files)

