def run_evals(cases, fn):
    results = []
    buckets = {}
    for c in cases:
        try:
            got = fn(c["input"])
        except Exception as e:
            row = {"id": c["id"], "ok": False, "got": None,
                   "error": f"{type(e).__name__}: {e}"}
        else:
            row = {"id": c["id"], "ok": _match(got, c["expected"]), "got": got}
        results.append(row)
        for tag in (c.get("tags") or ["untagged"]):
            buckets.setdefault(tag, []).append(row["ok"])

    by_tag = {}
    for tag in sorted(buckets):
        oks = buckets[tag]
        by_tag[tag] = {
            "total": len(oks),
            "passed": sum(1 for o in oks if o),
            "pass_rate": round(sum(1 for o in oks if o) / len(oks), 4),
        }

    passed = sum(1 for r in results if r["ok"])
    rate = round(passed / len(results), 4) if results else 0.0
    return {"results": results, "pass_rate": rate, "by_tag": by_tag}

def _exact(got, expected):
    return 1.0 if got == expected else 0.0

def _run_one(c, fn, table, threshold):
    name = c.get("grader", "exact")
    if name not in table:
        return {"id": c["id"], "ok": False, "got": None, "score": 0.0,
                "error": f"unknown grader: {name}"}
    try:
        got = fn(c["input"])
    except Exception as e:
        return {"id": c["id"], "ok": False, "got": None, "score": 0.0,
                "error": f"{type(e).__name__}: {e}"}
    score = round(float(table[name](got, c["expected"])), 4)
    return {"id": c["id"], "ok": score >= threshold, "got": got, "score": score}

def run_evals(cases, fn, graders=None, threshold=1.0):
    table = {"exact": _exact, **(graders or {})}
    results, buckets = [], {}
    for c in cases:
        row = _run_one(c, fn, table, threshold)
        results.append(row)
        for tag in (c.get("tags") or ["untagged"]):
            buckets.setdefault(tag, []).append(row)

    def agg(rows):
        n = len(rows)
        return {
            "total": n,
            "passed": sum(1 for r in rows if r["ok"]),
            "pass_rate": round(sum(1 for r in rows if r["ok"]) / n, 4),
            "mean_score": round(sum(r["score"] for r in rows) / n, 4),
        }

    by_tag = {tag: agg(buckets[tag]) for tag in sorted(buckets)}
    n = len(results)
    return {
        "results": results,
        "pass_rate": round(sum(1 for r in results if r["ok"]) / n, 4) if n else 0.0,
        "mean_score": round(sum(r["score"] for r in results) / n, 4) if n else 0.0,
        "by_tag": by_tag,
    }

import json

def assemble(events):
    blocks = {}
    for ev in events:
        t = ev.get("type")
        if t == "content_block_start":
            i = ev["index"]
            b = ev["block"]
            blocks[i] = {"kind": b["type"], "meta": b, "parts": []}
        elif t == "content_block_delta":
            i = ev["index"]
            if i not in blocks:
                continue
            d = ev["delta"]
            blocks[i]["parts"].append(d.get("text") or d.get("partial_json") or "")

    out = []
    for i in sorted(blocks):
        b = blocks[i]
        joined = "".join(b["parts"])
        if b["kind"] == "text":
            out.append({"type": "text", "text": joined})
        else:
            out.append({
                "type": "tool_use",
                "id": b["meta"]["id"],
                "name": b["meta"]["name"],
                "input": json.loads(joined) if joined.strip() else {},
            })
    return out

