import json

def assemble(events):
    blocks = {}

    def slot(i, kind="text", meta=None):
        return blocks.setdefault(i, {
            "kind": kind, "meta": meta or {}, "parts": [],
            "closed": False, "orphan": meta is None,
        })

    for ev in events:
        t = ev.get("type")
        if t == "content_block_start":
            b = ev["block"]
            blocks[ev["index"]] = {"kind": b["type"], "meta": b, "parts": [],
                                   "closed": False, "orphan": False}
        elif t == "content_block_delta":
            d = ev.get("delta") or {}
            s = slot(ev["index"])
            s["parts"].append(d.get("text") or d.get("partial_json") or "")
        elif t == "content_block_stop":
            if ev["index"] in blocks:
                blocks[ev["index"]]["closed"] = True

    out = []
    for i in sorted(blocks):
        b = blocks[i]
        joined = "".join(b["parts"])
        broken = b["orphan"] or not b["closed"]

        if b["kind"] == "text":
            item = {"type": "text", "text": joined}
        else:
            item = {"type": "tool_use", "id": b["meta"].get("id"),
                    "name": b["meta"].get("name")}
            try:
                item["input"] = json.loads(joined) if joined.strip() else {}
            except json.JSONDecodeError:
                item["input"] = None
                item["raw"] = joined
                broken = True

        if broken:
            item["incomplete"] = True
        out.append(item)
    return out

import json

def stream(events):
    pending = {}
    for ev in events:
        t = ev.get("type")
        if t == "content_block_start":
            b = ev["block"]
            if b["type"] == "tool_use":
                pending[ev["index"]] = [b.get("name"), []]
                yield ("tool_start", b.get("name"))
        elif t == "content_block_delta":
            d = ev.get("delta") or {}
            i = ev.get("index")
            if d.get("type") == "input_json_delta" and i in pending:
                pending[i][1].append(d.get("partial_json") or "")
            else:
                text = d.get("text") or ""
                if text:
                    yield ("text", text)
        elif t == "content_block_stop":
            i = ev.get("index")
            if i in pending:
                _, parts = pending.pop(i)
                raw = "".join(parts)
                try:
                    yield ("tool_input", json.loads(raw) if raw.strip() else {})
                except json.JSONDecodeError:
                    yield ("tool_error", raw)
    yield ("done", None)
